import java.util.Scanner;

public class Main {
    static long n;
    static long[] tmp = new long[20];

    static long minVal(long a, long b) {
        return (a < b) ? a : b;
    }

    static long compute(long num, int level) {
        if (num < 0) num = -num;
        long base = (num / tmp[level]) * level;
        long remaining = num - (num / tmp[level]) * tmp[level];
        if (remaining == 0) return base;
        return base + minVal(compute(remaining, level - 1), level + compute(tmp[level] - remaining, level - 1));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 1; i <= 18; ++i) {
            if (i == 1) tmp[i] = 1;
            else tmp[i] = tmp[i - 1] * 10 + 1;
        }
        n = sc.nextLong();
        long answer = compute(n, 17);
        System.out.println(answer);
        sc.close();
    }
}
